if (!window.__simplificaThemeSystemListenerConfigured) {
  window.__simplificaThemeSystemListenerConfigured = true;
  window.addEventListener("simplifica-theme-system-change", () => aplicarPersonalizacao());
}

function capturarScrollInterface() {
  if (typeof document === "undefined") return [];
  const snapshot = [];
  const registrar = (elemento, chave) => {
    if (!elemento) return;
    snapshot.push({
      chave,
      top: Number(elemento.scrollTop) || 0,
      left: Number(elemento.scrollLeft) || 0
    });
  };

  registrar(document.scrollingElement || document.documentElement, "__page");
  [
    ".mobile-home",
    ".mobile-panel-content",
    ".desktop-main",
    ".side-drawer",
    ".profile-premium-panel",
    ".popup-box",
    ".modal-card"
  ].forEach((seletor) => {
    document.querySelectorAll(seletor).forEach((elemento, index) => registrar(elemento, `${seletor}:${index}`));
  });

  return snapshot;
}

function restaurarScrollInterface(snapshot = []) {
  if (!Array.isArray(snapshot) || !snapshot.length || typeof document === "undefined") return;
  const obterElemento = (chave) => {
    if (chave === "__page") return document.scrollingElement || document.documentElement;
    const separador = chave.lastIndexOf(":");
    const seletor = chave.slice(0, separador);
    const index = Number(chave.slice(separador + 1)) || 0;
    return document.querySelectorAll(seletor)[index] || null;
  };
  const aplicar = () => {
    snapshot.forEach((item) => {
      const elemento = obterElemento(item.chave);
      if (!elemento) return;
      elemento.scrollTop = item.top;
      elemento.scrollLeft = item.left;
    });
  };
  requestAnimationFrame(() => {
    aplicar();
    requestAnimationFrame(aplicar);
  });
}

function renderizarPreservandoScroll() {
  const snapshot = capturarScrollInterface();
  renderApp();
  restaurarScrollInterface(snapshot);
}

function resetarScrollTelaAtiva() {
  if (typeof window === "undefined" || typeof document === "undefined") return;
  requestAnimationFrame(() => {
    try {
      window.scrollTo({ top: 0, left: 0, behavior: "auto" });
    } catch (_) {
      window.scrollTo(0, 0);
    }
    [
      ".desktop-main",
      ".desktop-focus",
      ".mobile-home",
      ".mobile-panel-content"
    ].forEach((seletor) => {
      document.querySelectorAll(seletor).forEach((elemento) => {
        elemento.scrollTop = 0;
        elemento.scrollLeft = 0;
      });
    });
  });
}

function agendarRenderizacaoPreservandoScroll(atraso = 120) {
  if (window.__simplificaRenderPreserveTimer) clearTimeout(window.__simplificaRenderPreserveTimer);
  window.__simplificaRenderPreserveTimer = setTimeout(() => {
    window.__simplificaRenderPreserveTimer = null;
    renderizarPreservandoScroll();
  }, Math.max(0, Number(atraso) || 0));
}

function iniciarTransicaoNavegacao(tipo = "forward") {
  if (typeof document === "undefined") return;
  clearTimeout(window.__simplificaMotionTimer);
  document.body.classList.remove("motion-forward", "motion-back", "motion-refresh");
  document.body.classList.add(`motion-${tipo}`);
  window.__simplificaMotionTimer = setTimeout(() => {
    document.body.classList.remove("motion-forward", "motion-back", "motion-refresh");
  }, 520);
}

function aplicarMotionSequenciado() {
  if (typeof document === "undefined") return;
  const animar = document.body.classList.contains("motion-forward")
    || document.body.classList.contains("motion-back")
    || window.__simplificaMotionPrimed !== true;
  if (!animar) return;
  window.__simplificaMotionPrimed = true;
  const alvos = [
    ".dashboard-kpis .kpi-card",
    ".dashboard-analytics-hero",
    ".analytics-kpi",
    ".dashboard-chart-card",
    ".dashboard-insights",
    ".insight-card",
    ".order-list-card",
    ".order-item-card",
    ".chart-card",
    ".plan-card",
    ".mobile-panel-content > .card",
    ".desktop-focus > .card",
    ".desktop-main > .card"
  ].join(",");
  document.querySelectorAll(alvos).forEach((elemento, index) => {
    if (index > 26) return;
    elemento.classList.add("motion-stagger-item");
    elemento.style.setProperty("--motion-index", String(index));
  });
}

function renderizarStatusSyncSeVisivel() {
  if (["backup", "config", "conta"].includes(telaAtual)) renderizarPreservandoScroll();
}

function sincronizarBannersSeNecessario(force = false) {
  const agora = Date.now();
  const chave = `${telaAtual}:${getPlanoAtual().status}:${isMobile() ? "m" : "d"}`;
  if (!force && window.__simplificaBannerSyncKey === chave && agora - Number(window.__simplificaBannerSyncAt || 0) < 1500) return;
  window.__simplificaBannerSyncKey = chave;
  window.__simplificaBannerSyncAt = agora;
  sincronizarBannerAdMob();
  sincronizarBannerAdSense();
}

function getParentScreenForBack(tela = telaAtual) {
  const pais = {
    assinatura: "conta",
    planos: "conta",
    minhaAssinatura: "conta",
    seguranca: "conta",
    empresa: "conta",
    preferencias: "config",
    personalizacao: "config",
    pdf: "config",
    backup: "config",
    pedido: "pedidos"
  };
  return pais[tela] || "dashboard";
}

function isDashboardRoute(tela = telaAtual) {
  return String(tela || "").trim() === "dashboard";
}

function fecharCamadaAtualSeExistir() {
  const popup = document.getElementById("popup");
  if (popup && popup.innerHTML.trim()) {
    fecharPopup();
    return true;
  }
  if (fecharNavegacaoContextualLojaSeExistir()) {
    return true;
  }
  if (sideDrawerOpen || document.querySelector(".side-drawer")) {
    fecharDrawerLateral();
    return true;
  }
  if (assistantOpen && typeof fecharAssistente === "function") {
    fecharAssistente();
    return true;
  }
  return false;
}

function fecharNavegacaoContextualLojaSeExistir() {
  if (storefrontGuidedPanelOpen || document.querySelector(".store-guided-editor-sidebar.is-open")) {
    fecharPainelEdicaoGuiadaLoja();
    return true;
  }
  const headerMenu = document.querySelector(".store-public-header.mobile-open");
  if (headerMenu) {
    headerMenu.classList.remove("mobile-open");
    return true;
  }
  return false;
}

function navegarVoltarLojaSeguroInterno() {
  if (telaAtual === "lojaAdmin") {
    abrirLojaPublicaAdminContextual({
      slug: getStorefrontAdminStoreLocal().slug || "ne3d-teste",
      view: "home"
    });
    return true;
  }
  if (telaAtual !== "lojaPublica") return false;

  const previousPath = storefrontPublicInternalHistory.pop();
  if (previousPath) {
    navegarLojaPublica(previousPath, { replace: true, restoreScroll: true });
    return true;
  }

  const route = getStorefrontPublicRoute();
  if (String(route.view || "home") !== "home") {
    navegarLojaPublica(getStorefrontPublicRoutePath({ slug: route.slug, view: "home" }), {
      replace: true,
      restoreScroll: true
    });
    return true;
  }

  trocarTela("lojaOnline", {
    resetStack: true,
    skipStack: true,
    replaceHistory: true
  });
  return true;
}

function navegarVoltarSeguroInterno() {
  if (fecharCamadaAtualSeExistir()) {
    atualizarHistoricoBrowserApp(true);
    return true;
  }
  if (navegarVoltarLojaSeguroInterno()) return true;
  if (isDashboardRoute()) return false;

  const destinoStack = navigationStack[navigationStack.length - 1];
  if (destinoStack && telas[destinoStack] && destinoStack !== telaAtual) {
    voltarTela();
    return true;
  }

  const destinoPai = getParentScreenForBack(telaAtual);
  trocarTela(telas[destinoPai] ? destinoPai : "dashboard", {
    resetStack: true,
    skipStack: true,
    replaceHistory: true
  });
  return true;
}

function atualizarHistoricoBrowserApp(replace = false) {
  if (typeof window === "undefined" || !window.history) return;
  const state = { simplifica: true, tela: telaAtual };
  try {
    if (replace) window.history.replaceState(state, document.title, window.location.href);
    else window.history.pushState(state, document.title, window.location.href);
  } catch (_) {}
}

function trocarTela(tela, opcoes = {}) {
  if (!telas[tela]) {
    tela = "dashboard";
  }

  if (!canAccessScreen(tela)) {
    registrarSeguranca("Acesso negado", "erro", "Tela: " + tela);
    tela = "acessoNegado";
  }

  const mudouTela = telaAtual !== tela;
  if (opcoes.resetStack) {
    navigationStack = [];
  }
  if (mudouTela) {
    if (!opcoes.skipStack && !opcoes.resetStack) {
      const anterior = telaAtual;
      const ultimo = navigationStack[navigationStack.length - 1];
      if (anterior && anterior !== tela && ultimo !== anterior) {
        navigationStack.push(anterior);
        if (navigationStack.length > 24) navigationStack = navigationStack.slice(-24);
      }
    }
    telaAnterior = opcoes.menuRoot ? "dashboard" : (opcoes.resetStack ? getParentScreenForBack(tela) : telaAtual);
  }

  telaAtual = tela;
  registrarEventoUsoLocal("tela_aberta", { tela });
  if (tela === "calculadora" && appConfig.calculatorWidget?.open) {
    appConfig.calculatorWidget.open = false;
    salvarDados();
  }
  if (mudouTela && !opcoes.fromHistory) {
    const rotaEspecial = parseStorefrontAdminRoute(location.pathname) || parseStorefrontPublicRoute(location.pathname);
    if (rotaEspecial && tela !== "lojaAdmin" && tela !== "lojaPublica") {
      try {
        history.pushState({ simplifica: true, tela }, document.title, "/");
      } catch (_) {
        atualizarHistoricoBrowserApp(!!opcoes.replaceHistory);
      }
    } else {
      atualizarHistoricoBrowserApp(!!opcoes.replaceHistory);
    }
  }
  if (mudouTela) iniciarTransicaoNavegacao(tela === "dashboard" ? "back" : "forward");
  renderApp();
  if (mudouTela) resetarScrollTelaAtiva();
}

function voltarTela() {
  if (fecharCamadaAtualSeExistir()) return;
  const destinoStack = navigationStack.pop();
  const destino = telas[destinoStack] ? destinoStack : (telas[telaAnterior] ? telaAnterior : getParentScreenForBack(telaAtual));
  const atual = telaAtual;
  telaAtual = destino;
  telaAnterior = navigationStack[navigationStack.length - 1] || getParentScreenForBack(destino);
  iniciarTransicaoNavegacao("back");
  atualizarHistoricoBrowserApp(true);
  renderApp();
  if (atual !== destino) resetarScrollTelaAtiva();
}

function voltarInicio() {
  telaAnterior = telaAtual;
  navigationStack = [];
  telaAtual = "dashboard";
  iniciarTransicaoNavegacao("back");
  atualizarHistoricoBrowserApp(true);
  renderApp();
}

async function lidarComVoltarSistema(event = null) {
  return handleAndroidBackPress({ source: "system", event });
}

async function solicitarConfirmacaoSaidaAndroid() {
  if (androidBackConfirmOpen) return false;
  androidBackConfirmOpen = true;
  try {
    return await solicitarConfirmacaoAcao({
      titulo: "Sair do aplicativo",
      mensagem: "Deseja realmente sair do aplicativo?",
      confirmar: "Sair",
      cancelar: "Cancelar",
      perigo: false
    });
  } catch (erro) {
    registrarDiagnostico("Navegação", "Confirmação de saída falhou", erro?.message || String(erro || ""));
    return window.confirm("Deseja realmente sair do aplicativo?");
  } finally {
    androidBackConfirmOpen = false;
  }
}

function sairAplicativoAndroidConfirmado() {
  if (androidBackExitInProgress) return true;
  androidBackExitInProgress = true;
  try {
    const appPlugin = window.Capacitor?.Plugins?.App;
    if (isAndroidNativeApp() && appPlugin?.exitApp) {
      appPlugin.exitApp();
      return true;
    }
  } catch (erro) {
    registrarDiagnostico("Navegação", "Falha ao fechar APK", erro?.message || String(erro || ""));
  } finally {
    setTimeout(() => {
      androidBackExitInProgress = false;
    }, 1600);
  }
  return false;
}

async function handleAndroidBackPress(opcoes = {}) {
  const dados = opcoes && typeof opcoes === "object" && ("source" in opcoes || "event" in opcoes || "nativeEvent" in opcoes)
    ? opcoes
    : { source: "event", event: opcoes };
  const evento = dados.event || dados.nativeEvent || null;
  evento?.preventDefault?.();
  const origem = String(dados.source || "");
  const agora = Date.now();
  if (androidBackConfirmOpen) return true;
  if (origem !== "popstate" && agora - lastAndroidBackHandledAt < 450) return true;
  lastAndroidBackHandledAt = agora;

  if (navegarVoltarSeguroInterno()) return true;

  if (!isDashboardRoute()) {
    trocarTela("dashboard", { resetStack: true, skipStack: true, replaceHistory: true });
    return true;
  }

  atualizarHistoricoBrowserApp(true);
  const confirmou = await solicitarConfirmacaoSaidaAndroid();
  if (!confirmou) {
    lastDashboardBackPromptAt = Date.now();
    mostrarToast("Saída cancelada.", "info", 1800);
    atualizarHistoricoBrowserApp(true);
    return true;
  }

  if (!sairAplicativoAndroidConfirmado()) {
    mostrarToast("Não foi possível fechar o app automaticamente.", "erro", 2600);
    atualizarHistoricoBrowserApp(true);
  }
  return true;
}

function removerAndroidBackHandler() {
  try {
    androidBackButtonListener?.remove?.();
  } catch (_) {}
  androidBackButtonListener = null;
  window.__simplificaAndroidBackHandlerConfigured = false;
}

function registrarAndroidBackHandler() {
  if (!isAndroidNativeApp()) return;
  const appPlugin = window.Capacitor?.Plugins?.App;
  if (!appPlugin?.addListener || window.__simplificaAndroidBackHandlerConfigured) return;
  window.__simplificaAndroidBackHandlerConfigured = true;
  try {
    const listener = appPlugin.addListener("backButton", (event) => {
      handleAndroidBackPress({ source: "capacitor-back", nativeEvent: event });
    });
    if (listener?.then) {
      listener
        .then((handle) => {
          androidBackButtonListener = handle;
        })
        .catch((erro) => {
          window.__simplificaAndroidBackHandlerConfigured = false;
          registrarDiagnostico("Navegação", "BackHandler Android não registrado", erro?.message || String(erro || ""));
        });
    } else {
      androidBackButtonListener = listener;
    }
  } catch (erro) {
    window.__simplificaAndroidBackHandlerConfigured = false;
    registrarDiagnostico("Navegação", "BackHandler Android falhou", erro?.message || String(erro || ""));
  }
}

function configurarNavegacaoInternaApp() {
  if (window.__simplificaNavigationConfigured) return;
  window.__simplificaNavigationConfigured = true;
  atualizarHistoricoBrowserApp(true);
  window.addEventListener("popstate", (event) => {
    const adminRoute = parseStorefrontAdminRoute(location.pathname);
    if (adminRoute) {
      telaAtual = "lojaAdmin";
      renderApp();
      return;
    }
    const publicRoute = parseStorefrontPublicRoute(location.pathname);
    if (publicRoute) {
      salvarScrollLojaPublica();
      storefrontPublicRouteState = publicRoute;
      storefrontPublicLastPath = getStorefrontPublicRoutePath(publicRoute);
      if (storefrontPublicInternalHistory[storefrontPublicInternalHistory.length - 1] === storefrontPublicLastPath) {
        storefrontPublicInternalHistory.pop();
      }
      telaAtual = "lojaPublica";
      marcarLojaPublicaNavegando();
      renderApp();
      restaurarScrollLojaPublica(storefrontPublicLastPath, 0);
      return;
    }
    handleAndroidBackPress({ source: "popstate", event });
  });
  configurarNavegacaoLojaPublica();
  registrarAndroidBackHandler();
  window.addEventListener("beforeunload", removerAndroidBackHandler);
}

function configurarProtecaoGestosMobile() {
  if (window.__simplificaGestureGuardConfigured) return;
  window.__simplificaGestureGuardConfigured = true;
  let inicioX = 0;
  let inicioY = 0;
  let protegendoToque = false;
  let ponteiroProtegidoId = null;
  let ponteiroInicioX = 0;
  let ponteiroInicioY = 0;

  const deveProteger = () => isMobile() || isAndroidNativeApp() || getPlatformAdapter().isPWA;
  const permiteHorizontal = (alvo) => !!alvo?.closest?.([
    "[data-allow-horizontal-scroll]",
    ".order-filter-chips",
    ".reports-period-tabs",
    ".reports-period-table",
    ".material-chip-row",
    ".filter-chip-row",
    ".table-scroll",
    ".scroll-x"
  ].join(","));
  const gestoHorizontalDominante = (dx, dy, limite = 18) => Math.abs(dx) > limite && Math.abs(dx) > Math.abs(dy) * 1.15;

  document.addEventListener("touchstart", (event) => {
    if (!deveProteger() || !event.touches?.length) return;
    const toque = event.touches[0];
    inicioX = toque.clientX;
    inicioY = toque.clientY;
    const largura = window.innerWidth || document.documentElement.clientWidth || 0;
    const toqueNaBorda = inicioX <= 28 || (largura > 0 && inicioX >= largura - 28);
    protegendoToque = toqueNaBorda || isAndroidNativeApp() || !!event.target?.closest?.(".mobile-panel, .side-drawer, .modal-backdrop, .mobile-bottom-nav");
  }, { passive: true, capture: true });

  document.addEventListener("touchmove", (event) => {
    if (!protegendoToque || !event.touches?.length || permiteHorizontal(event.target)) return;
    const toque = event.touches[0];
    const dx = toque.clientX - inicioX;
    const dy = toque.clientY - inicioY;
    if (gestoHorizontalDominante(dx, dy)) {
      event.preventDefault();
      event.stopPropagation();
    }
  }, { passive: false, capture: true });

  document.addEventListener("touchend", () => {
    protegendoToque = false;
  }, { passive: true, capture: true });

  document.addEventListener("touchcancel", () => {
    protegendoToque = false;
  }, { passive: true, capture: true });

  document.addEventListener("pointerdown", (event) => {
    if (!deveProteger() || event.pointerType === "mouse") return;
    ponteiroProtegidoId = event.pointerId;
    ponteiroInicioX = event.clientX;
    ponteiroInicioY = event.clientY;
  }, { passive: true, capture: true });

  document.addEventListener("pointermove", (event) => {
    if (ponteiroProtegidoId !== event.pointerId || event.pointerType === "mouse" || permiteHorizontal(event.target)) return;
    const dx = event.clientX - ponteiroInicioX;
    const dy = event.clientY - ponteiroInicioY;
    if (gestoHorizontalDominante(dx, dy, 22)) {
      event.preventDefault();
      event.stopPropagation();
    }
  }, { passive: false, capture: true });

  const limparPonteiro = (event) => {
    if (ponteiroProtegidoId === event.pointerId) ponteiroProtegidoId = null;
  };
  document.addEventListener("pointerup", limparPonteiro, { passive: true, capture: true });
  document.addEventListener("pointercancel", limparPonteiro, { passive: true, capture: true });
}

if (typeof window !== "undefined") {
  window.handleAndroidBackPress = handleAndroidBackPress;
  window.isDashboardRoute = isDashboardRoute;
}

function ensureAppShellLayers() {
  if (typeof document === "undefined") return null;
  const app = document.getElementById("app");
  let shell = document.getElementById(APP_LAYER_IDS.shell);
  if (!shell && app?.parentElement) {
    shell = document.createElement("div");
    shell.id = APP_LAYER_IDS.shell;
    shell.className = "app-shell";
    shell.dataset.shellVersion = APP_SHELL_VERSION;
    app.parentElement.insertBefore(shell, app);
    const content = document.createElement("main");
    content.id = APP_LAYER_IDS.content;
    content.className = "app-content-shell";
    shell.appendChild(criarAppShellSlot("aside", APP_LAYER_IDS.sidebar, "app-shell-slot app-sidebar-slot"));
    shell.appendChild(criarAppShellSlot("header", APP_LAYER_IDS.topbar, "app-shell-slot app-topbar-slot"));
    shell.appendChild(content);
    content.appendChild(app);
  }
  if (!shell) return null;
  shell.dataset.shellVersion = APP_SHELL_VERSION;
  garantirFilhoAppShell(shell, "aside", APP_LAYER_IDS.sidebar, "app-shell-slot app-sidebar-slot", true);
  garantirFilhoAppShell(shell, "header", APP_LAYER_IDS.topbar, "app-shell-slot app-topbar-slot", true);
  const content = garantirFilhoAppShell(shell, "main", APP_LAYER_IDS.content, "app-content-shell", false);
  if (app && content && app.parentElement !== content) content.appendChild(app);
  garantirFilhoAppShell(shell, "div", APP_LAYER_IDS.overlay, "app-layer app-overlay-layer", false);
  garantirFilhoAppShell(shell, "div", APP_LAYER_IDS.drawer, "app-layer app-drawer-layer", false);
  garantirFilhoAppShell(shell, "div", APP_LAYER_IDS.modal, "app-layer app-modal-layer", false);
  garantirFilhoAppShell(shell, "div", APP_LAYER_IDS.toast, "app-layer app-toast-layer", false);
  document.body?.classList.add("app-shell-ready");
  return shell;
}

function criarAppShellSlot(tag, id, className, hidden = false) {
  const el = document.createElement(tag);
  el.id = id;
  el.className = className;
  if (hidden) el.setAttribute("aria-hidden", "true");
  return el;
}

function garantirFilhoAppShell(shell, tag, id, className, hidden = false) {
  let el = document.getElementById(id);
  if (!el) {
    el = criarAppShellSlot(tag, id, className, hidden);
    shell.appendChild(el);
  } else if (el.parentElement !== shell && id !== APP_LAYER_IDS.content) {
    shell.appendChild(el);
  }
  const estavaAtivo = el.classList?.contains("is-active") || !!String(el.innerHTML || "").trim();
  el.className = className;
  if (estavaAtivo) el.classList.add("is-active");
  if (hidden) el.setAttribute("aria-hidden", "true");
  return el;
}

function getAppLayer(layer = "modal") {
  ensureAppShellLayers();
  return document.getElementById(APP_LAYER_IDS[layer] || layer);
}

function setAppLayerContent(layer, html = "", options = {}) {
  const alvo = getAppLayer(layer);
  if (!alvo) return null;
  alvo.innerHTML = html || "";
  alvo.classList.toggle("is-active", !!html);
  if (options.label) alvo.setAttribute("aria-label", options.label);
  if (options.role) alvo.setAttribute("role", options.role);
  syncAppShellLayerState();
  return alvo;
}

function syncAppShellLayerState() {
  if (typeof document === "undefined" || !document.body) return;
  const modalAtivo = document.getElementById(APP_LAYER_IDS.modal)?.classList.contains("is-active") === true;
  const drawerAtivo = document.getElementById(APP_LAYER_IDS.drawer)?.classList.contains("is-active") === true;
  const overlayAtivo = document.getElementById(APP_LAYER_IDS.overlay)?.classList.contains("is-active") === true;
  document.body.classList.toggle("app-modal-open", modalAtivo);
  document.body.classList.toggle("app-drawer-open", drawerAtivo);
  document.body.classList.toggle("app-layer-open", modalAtivo || drawerAtivo || overlayAtivo);
}

function normalizeLayerOptions(input = "", options = {}) {
  if (input && typeof input === "object" && !Array.isArray(input)) {
    return { ...input };
  }
  return { ...options, content: input };
}

function renderOverlayScrim(options = {}) {
  const closeAction = options.closeAction || "";
  return `<div class="app-overlay-scrim" aria-hidden="true" ${closeAction ? `onclick="${escaparAttr(closeAction)}"` : ""}></div>`;
}

function openModal(input = "", options = {}) {
  const config = normalizeLayerOptions(input, options);
  const content = config.content || config.html || "";
  if (!content) return null;
  if (config.overlay !== false) showOverlay(null, { closeAction: config.closable === false ? "" : "closeModal()" });
  const size = config.size ? ` app-modal-size-${String(config.size).replace(/[^a-z0-9_-]/gi, "")}` : "";
  const html = `<div class="app-modal-stage${size}" onclick="event.stopPropagation()">${content}</div>`;
  return setAppLayerContent("modal", html, { role: "dialog", label: config.label || "Modal" });
}

function closeModal() {
  setAppLayerContent("modal", "");
  hideOverlay();
}

function openDrawer(input = "", options = {}) {
  const config = normalizeLayerOptions(input, options);
  const content = config.content || config.html || "";
  if (!content) return null;
  if (config.overlay !== false) showOverlay(null, { closeAction: config.closable === false ? "" : "closeDrawer()" });
  return setAppLayerContent("drawer", content, { role: "dialog", label: config.label || "Drawer" });
}

function closeDrawer() {
  sideDrawerOpen = false;
  sideDrawerProgress = 0;
  sideDrawerGesture = null;
  setAppLayerContent("drawer", "");
  hideOverlay();
}

function showOverlay(html = null, options = {}) {
  return setAppLayerContent("overlay", html || renderOverlayScrim(options), options);
}

function hideOverlay() {
  setAppLayerContent("overlay", "");
}

function showToast(mensagem, tipo = "info", duracao = 4200) {
  return mostrarToast(mensagem, tipo, duracao);
}

function hideToast() {
  const area = document.getElementById("toastArea");
  if (area) area.innerHTML = "";
}

if (typeof window !== "undefined") {
  Object.assign(window, {
    openModal,
    closeModal,
    openDrawer,
    closeDrawer,
    showToast,
    hideToast,
    showOverlay,
    hideOverlay
  });
}

function atualizarMenu() {
  document.querySelectorAll(".menu-button, .side-nav-button, .popup-nav-button, .mobile-bottom-nav-button").forEach((botao) => {
    botao.classList.toggle("active", botao.dataset.tela === telaAtual);
  });
}

function renderApp() {
  ensureAppShellLayers();
  const app = document.getElementById("app");
  if (!app) return;
  applyViewportModeClasses(document.body);
  if (window.__simplificaLocalLockActive && getUsuarioAtual()) {
    aplicarPersonalizacao();
    app.innerHTML = renderTravaLocal();
    renderCalculadoraFlutuante();
    sincronizarBannersSeNecessario();
    setTimeout(() => document.getElementById("localUnlockPassword")?.focus(), 80);
    return;
  }
  if (!getUsuarioAtual() && !adminLogado && !isTelaPublica(telaAtual)) {
    telaAtual = "admin";
  }
  if (telaAtual === "dashboard" && deveMostrarOnboarding()) {
    telaAtual = "onboarding";
  }

  aplicarPersonalizacao();
  const viewportMode = applyViewportModeClasses(document.body);
  const mobile = viewportMode === "mobile";
  document.body.classList.toggle("mobile-mode", mobile);
  document.body.classList.toggle("tablet-mode", viewportMode === "tablet");
  document.body.classList.toggle("desktop-mode", viewportMode === "desktop");
  document.body.classList.toggle("auth-screen-active", !getUsuarioAtual() && telaAtual === "admin");
  app.innerHTML = (mobile ? renderMobile() : renderDesktop()) + (HEAVY_AI_FEATURE_ENABLED && podeMostrarControlesFlutuantes() ? renderAssistenteVirtual() : "");
  atualizarMenu();
  ajustarJanelasDashboardAoWorkspace(false);
  renderCalculadoraFlutuante();
  sincronizarBannersSeNecessario();
  hidratarLojaPublicaSeNecessario();
  preencherImpressoras();
  preencherMateriaisCalculadora();
  aplicarMotionSequenciado();
  hidratarLojaOnlineAdmin();
}

function podeMostrarControlesFlutuantes() {
  return !!getUsuarioAtual() && !window.__simplificaLocalLockActive && !isTelaPublica(telaAtual) && telaAtual !== "onboarding" && telaAtual !== "dashboard";
}

const STOREFRONT_BETA_ACCESS_KEY = "simplifica-storefront-beta-access-v1";
const STOREFRONT_TRUE_VALUES = new Set(["true", "1", "yes", "sim", "on"]);
const STOREFRONT_UPLOAD_STATUS_KEY = "simplifica-storefront-upload-status-v1";
const STOREFRONT_PUBLIC_RELEASE = true;

function isStorefrontTruthy(value) {
  return STOREFRONT_TRUE_VALUES.has(String(value ?? "").trim().toLowerCase());
}

function getStorefrontBetaAccessCache() {
  try {
    const cache = JSON.parse(localStorage.getItem(STOREFRONT_BETA_ACCESS_KEY) || "{}");
    return cache && typeof cache === "object" ? cache : {};
  } catch (_) {
    return {};
  }
}

function setStorefrontBetaAccessCache(access) {
  try {
    localStorage.setItem(STOREFRONT_BETA_ACCESS_KEY, JSON.stringify({
      ...access,
      updatedAt: new Date().toISOString()
    }));
  } catch (_) {}
}

function isStorefrontDevOverrideEnabled() {
  if (!isAmbienteLocal()) return false;
  try {
    return isStorefrontTruthy(localStorage.getItem("STORE_FRONT_ENABLED"))
      || isStorefrontTruthy(localStorage.getItem("simplifica3d:storefront-enabled"));
  } catch (_) {
    return false;
  }
}

function getStorefrontRuntimeFlags() {
  const valorGlobal = String(window.STORE_FRONT_ENABLED ?? window.__STORE_FRONT_ENABLED__ ?? "").toLowerCase();
  const beta = getStorefrontBetaAccessCache();
  const devOverride = isStorefrontDevOverrideEnabled();
  return {
    publicRelease: STOREFRONT_PUBLIC_RELEASE,
    enabledByEnv: isStorefrontTruthy(valorGlobal),
    enabledByRemote: beta.enabled === true,
    betaAllowedByRemote: beta.allowed === true,
    devOverride,
    checkedAt: beta.updatedAt || ""
  };
}

function isStorefrontFeatureEnabled(flags = getStorefrontRuntimeFlags()) {
  return flags.publicRelease === true || flags.enabledByEnv || flags.enabledByRemote || flags.devOverride;
}

function registrarStorefrontDebugLeve(evento, detalhe = "", extra = {}) {
  try {
    const payload = {
      evento,
      detalhe,
      extra,
      tela: telaAtual || "",
      at: new Date().toISOString()
    };
    console.warn(`[Storefront] ${evento}: ${detalhe}`, extra || "");
    const key = "simplifica-storefront-debug-v1";
    const current = JSON.parse(localStorage.getItem(key) || "[]");
    current.unshift(payload);
    localStorage.setItem(key, JSON.stringify(current.slice(0, 40)));
  } catch (_) {}
}

function setStorefrontUploadStatus(status = {}) {
  try {
    localStorage.setItem(STOREFRONT_UPLOAD_STATUS_KEY, JSON.stringify({
      type: status.type || "info",
      title: status.title || "",
      message: status.message || "",
      detail: status.detail || "",
      at: new Date().toISOString()
    }));
  } catch (_) {}
}

function clearStorefrontUploadStatus() {
  try {
    localStorage.removeItem(STOREFRONT_UPLOAD_STATUS_KEY);
  } catch (_) {}
}

function getStorefrontUploadStatus() {
  try {
    const saved = JSON.parse(localStorage.getItem(STOREFRONT_UPLOAD_STATUS_KEY) || "null");
    return saved && typeof saved === "object" ? saved : null;
  } catch (_) {
    return null;
  }
}

function renderStorefrontUploadStatus() {
  const status = getStorefrontUploadStatus();
  if (!status?.title && !status?.message) return "";
  return `
    <div class="storefront-upload-status ${escaparAttr(status.type || "info")}" data-storefront-upload-status>
      <strong>${escaparHtml(status.title || "Status do upload")}</strong>
      ${status.message ? `<span>${escaparHtml(status.message)}</span>` : ""}
      ${status.detail ? `<small>${escaparHtml(status.detail)}</small>` : ""}
    </div>
  `;
}

function isStorefrontAllowedTestUser(usuario = getUsuarioAtual(), flags = getStorefrontRuntimeFlags()) {
  const email = normalizarEmail(usuario?.email || usuarioAtualEmail || syncConfig.supabaseEmail || "");
  const permitidos = new Set([
    "neprintshop9790@gmail.com",
    "teste@simplifica3d.local",
    "storefront@simplifica3d.local"
  ]);
  if (isSuperAdmin(usuario)) return true;
  if (flags.betaAllowedByRemote) return true;
  return (flags.enabledByEnv || flags.devOverride) && permitidos.has(email);
}

function getStorefrontLimitsLocal(userPlan = getPlanoAtual()?.slug || "free") {
  const plano = normalizarSlugPlano(userPlan || "free");
  const entitlements = getPlanEntitlements(plano);
  const limits = getPlanLimits(plano);
  const pro = ["pro", "premium_trial"].includes(plano);
  return {
    enabled: true,
    publishEnabled: entitlements.publicStore === true,
    shareEnabled: entitlements.shareLink === true,
    productLimit: limits.storefrontProducts,
    leadsEnabled: entitlements.publicStore === true,
    qrCodeEnabled: entitlements.shareLink === true,
    customThemeEnabled: entitlements.basicCustomization === true,
    premiumThemeEnabled: pro,
    metricsEnabled: entitlements.advancedReports === true,
    simplificaBrandingRequired: entitlements.publicStore !== true
  };
}

function canAccessStorefrontAdmin(usuario = getUsuarioAtual(), plan = getPlanoAtual(usuario), flags = getStorefrontRuntimeFlags()) {
  if (!usuario) {
    registrarStorefrontDebugLeve("sessao_perdida", "Acesso ao admin da loja sem usuário autenticado.");
    return false;
  }
  // Fase atual: editor liberado para qualquer usuário autenticado.
  return true;
}

function canUseStorefrontLocal(usuario = getUsuarioAtual()) {
  return canAccessStorefrontAdmin(usuario, getPlanoAtual(usuario), getStorefrontRuntimeFlags());
}

async function sincronizarStorefrontBetaAccessRemoto(force = false) {
  const usuario = getUsuarioAtual();
  if (!usuario || !storefrontAdminRemoteReady()) return;
  const cache = getStorefrontBetaAccessCache();
  if (!force && cache.updatedAt && Date.now() - Date.parse(cache.updatedAt) < 180000) return;
  try {
    const userId = encodeURIComponent(syncConfig.supabaseUserId || "");
    const email = encodeURIComponent(normalizarEmail(usuario.email || syncConfig.supabaseEmail || ""));
    if (!userId && !email) return;
    const query = `/rest/v1/storefront_beta_users?select=id,user_id,email,enabled&enabled=eq.true&or=(user_id.eq.${userId},email.eq.${email})&limit=1`;
    const rows = await storefrontAdminRequest(query, { timeoutMs: 7000 });
    const allowed = Array.isArray(rows) && rows.some((row) => row?.enabled === true);
    setStorefrontBetaAccessCache({ enabled: allowed, allowed });
    if (allowed && telaAtual !== "lojaOnline") renderApp();
  } catch (error) {
    if (/storefront_beta_users|schema cache|PGRST205/i.test(String(error?.message || error))) {
      setStorefrontBetaAccessCache({ enabled: false, allowed: false, schemaMissing: true });
      return;
    }
    if (force) mostrarToast("Não foi possível validar o acesso da Loja Online agora.", "erro", 3600);
    console.warn("[Storefront admin] beta access check failed", error);
  }
}

function renderDesktop() {
  if (telaAtual === "lojaPublica") {
    return renderTela("lojaPublica");
  }
  if (telaAtual === "lojaAdmin") {
    return renderStorefrontAdminStandalone();
  }
  if (!getUsuarioAtual() && telaAtual === "admin") {
    return `<main class="auth-desktop-main">${renderAdmin()}</main>`;
  }
  const classeMenu = appConfig.sidebarCollapsed ? " sidebar-collapsed" : "";
  return `
    <div class="desktop-shell s3d-shell${classeMenu}">
      ${renderMenuLateral()}
      <main class="desktop-main app-content s3d-shell-main">
        ${renderTopbar()}
        ${renderDesktopConteudo()}
      </main>
    </div>
  `;
}

function renderDesktopConteudo() {
  if (!canAccessScreen(telaAtual)) {
    return `<div class="desktop-focus app-page">${renderAcessoNegado()}</div>`;
  }

  if (getUsuarioAtual()?.mustChangePassword && telaAtual !== "seguranca") {
    return `<div class="desktop-focus app-page">${renderTrocaSenhaObrigatoria()}</div>`;
  }

  const configuracoes = ["config", "backup", "personalizacao", "empresa", "preferencias", "pdf", "mais", "conta", "assinatura", "minhaAssinatura", "planos", "admin", "usuarios", "seguranca", "lojaOnline", "lojaAdmin", "superadmin", "privacy", "terms", "acessoNegado"];
  const atualizacaoAndroid = renderAtualizacaoAndroidDownload();

  if (configuracoes.includes(telaAtual)) {
    return `<div class="desktop-focus app-page">${atualizacaoAndroid}${renderTela(telaAtual)}</div>`;
  }

  if (telaAtual !== "dashboard") {
    return `<div class="desktop-focus app-page desktop-page-${escaparAttr(telaAtual)}">${atualizacaoAndroid}${renderTela(telaAtual)}</div>`;
  }

  return `${atualizacaoAndroid}${renderDashboard()}`;
}

