  const statusModelo = getAIModelStatus(modeloLocal?.id || AI_LOCAL_MEDIUM_MODEL_ID);
  const progress = progressoIAInstalacao(getAIModelLocalState(modeloLocal?.id || AI_LOCAL_MEDIUM_MODEL_ID));
