function getStorefrontPublicUrlLocal() {
  const origem = location.origin && location.origin !== "null" ? location.origin : "";
  return `${origem}/loja/ne3d-teste`;
}

function copiarLinkLojaOnline() {
  const link = getStorefrontPublicUrlLocal();
  if (navigator.clipboard?.writeText) {
    navigator.clipboard.writeText(link).then(() => mostrarToast("Link da loja copiado.", "sucesso", 2600)).catch(() => prompt("Copie o link da loja:", link));
    return;
  }
  prompt("Copie o link da loja:", link);
}

async function transformarLeadLojaOnlinePreview(id) {
  if (String(id || "").startsWith("demo-")) {
    mostrarToast("Este contato é apenas um exemplo e não gera pedido.", "info", 3200);
    return;
  }
  const leads = getStorefrontPreviewLeadsLocal();
  const lead = leads.find((item) => String(item.id) === String(id));
  if (!lead) {
    mostrarToast("Contato não encontrado na visualização.", "erro", 3200);
    return;
  }
  const draft = {
    id: `draft-${Date.now()}`,
    store_id: lead.store_id,
    owner_id: lead.owner_id,
    lead_id: lead.id,
    customer_name: lead.customer_name || "",
    customer_phone: lead.customer_phone || "",
    items_json: lead.items_json || [],
    subtotal: Number(lead.subtotal || 0),
    status: "rascunho",
    created_at: new Date().toISOString()
  };
  try {
    if (storefrontAdminRemoteReady() && !storefrontAdminIsLocalId(id)) {
      const rows = await storefrontAdminRequest("/rest/v1/store_order_drafts", {
        method: "POST",
        headers: { Prefer: "return=representation" },
        body: JSON.stringify({
          store_id: lead.store_id,
          owner_id: storefrontAdminCurrentOwnerId(),
          lead_id: lead.id,
          customer_name: lead.customer_name || null,
          customer_phone: lead.customer_phone || null,
          items_json: lead.items_json || [],
          subtotal: Number(lead.subtotal || 0),
          status: "rascunho"
        })
      });
      await storefrontAdminRequest(`/rest/v1/store_cart_leads?id=eq.${encodeURIComponent(id)}`, {
        method: "PATCH",
        headers: { Prefer: "return=minimal" },
        body: JSON.stringify({ status: "convertido" })
      });
      if (rows?.[0]) draft.id = rows[0].id;
    }
    const drafts = storefrontAdminRead("simplifica-storefront-order-drafts-preview-v1", []);
    storefrontAdminWrite("simplifica-storefront-order-drafts-preview-v1", [draft, ...(Array.isArray(drafts) ? drafts : [])].slice(0, 100));
    storefrontAdminWrite("simplifica-storefront-leads-preview-v1", leads.map((item) => String(item.id) === String(id) ? { ...item, status: "convertido" } : item));
    mostrarToast("Pedido rascunho criado para revisão manual.", "sucesso", 3600);
    renderApp();
  } catch (error) {
    mostrarToast("Não foi possível transformar o contato em pedido agora.", "erro", 4200);
    console.error("[Storefront admin] transformar lead", error);
  }
}

const STOREFRONT_ADMIN_KEYS = {
  tab: "simplifica-storefront-admin-tab-v1",
  store: "simplifica-storefront-admin-store-v1",
  categories: "simplifica-storefront-admin-categories-v1",
  products: "simplifica-storefront-admin-products-v1",
  images: "simplifica-storefront-admin-images-v1",
  editingCategory: "simplifica-storefront-admin-editing-category-v1",
  editingProduct: "simplifica-storefront-admin-editing-product-v1",
  editingProductSeed: "simplifica-storefront-admin-editing-product-seed-v1",
  lastRemoteSync: "simplifica-storefront-admin-last-remote-sync-v1",
  dirty: "simplifica-storefront-admin-dirty-v1",
  activity: "simplifica-storefront-admin-activity-v1",
  editorMode: "simplifica-storefront-admin-editor-mode-v1",
  autosave: "simplifica-storefront-admin-autosave-v1",
  recovery: "simplifica-storefront-admin-recovery-v1",
  offlineQueue: "simplifica-storefront-admin-offline-queue-v1"
};
const STOREFRONT_THEME_STORAGE_KEY = "simplifica3d_store_theme_preference";
const STOREFRONT_THEME_LEGACY_STORAGE_KEY = "simplifica3d_store_theme";
const STOREFRONT_THEME_COLORS = Object.freeze({
  light: "#f2f5f4",
  dark: "#08131d"
});

function normalizarTemaLojaOnline(theme = "") {
  return window.SimplificaThemeAuthorityV2?.normalizePreference?.(theme, "light")
    || normalizarPreferenciaTemaInterface(theme);
}

function getStoreThemeSaved() {
  if (window.SimplificaThemeAuthorityV2?.getSavedStoreThemePreference) {
    return window.SimplificaThemeAuthorityV2.getSavedStoreThemePreference();
  }
  try {
    return normalizarTemaLojaOnline(localStorage.getItem(STOREFRONT_THEME_STORAGE_KEY) || localStorage.getItem(STOREFRONT_THEME_LEGACY_STORAGE_KEY));
  } catch (_) {
    return "light";
  }
}

function updateStorefrontThemeColor(theme = "light") {
  const resolvedTheme = getEffectiveThemeMode(theme);
  if (window.SimplificaThemeAuthorityV2?.updateThemeColor) {
    return window.SimplificaThemeAuthorityV2.updateThemeColor(resolvedTheme);
  }
  const themeMeta = document.querySelector("meta[name='theme-color']");
  if (themeMeta) themeMeta.setAttribute("content", STOREFRONT_THEME_COLORS[resolvedTheme]);
  return resolvedTheme;
}

function applyStoreTheme(theme = "light", { persist = true } = {}) {
  const preference = normalizarTemaLojaOnline(theme);
  if (window.SimplificaThemeAuthorityV2?.applyStoreTheme) {
    return window.SimplificaThemeAuthorityV2.applyStoreTheme(preference, { persist }).resolved;
  }
  const resolvedTheme = getEffectiveThemeMode(preference);
  document.documentElement.setAttribute("data-store-theme", resolvedTheme);
  document.documentElement.setAttribute("data-store-theme-preference", preference);
  document.body?.setAttribute("data-store-theme", resolvedTheme);
  document.body?.setAttribute("data-store-theme-preference", preference);
  document.querySelectorAll?.(".store-public-shell").forEach((shell) => {
    shell.classList.add("storefront-theme-v2");
    shell.setAttribute("data-store-theme", resolvedTheme);
    shell.setAttribute("data-store-theme-preference", preference);
  });
  updateStorefrontThemeColor(resolvedTheme);
  if (persist) {
    try {
      localStorage.setItem(STOREFRONT_THEME_STORAGE_KEY, preference);
      localStorage.setItem(STOREFRONT_THEME_LEGACY_STORAGE_KEY, resolvedTheme);
    } catch (_) {}
  }
  return resolvedTheme;
}

if (typeof window !== "undefined") {
  window.SimplificaStoreTheme = Object.freeze({
    apply: applyStoreTheme,
    getSaved: getStoreThemeSaved,
    normalize: normalizarTemaLojaOnline,
    resolve: getEffectiveThemeMode,
    updateThemeColor: updateStorefrontThemeColor
  });
}

const STOREFRONT_ADMIN_TABS = [
  ["overview", "Visão geral"],
  ["appearance", "Aparência"],
  ["products", "Produtos da loja"],
  ["categories", "Categorias"],
  ["banner", "Banner"],
  ["leads", "Contatos/Pedidos"],
  ["qrcode", "Compartilhamento"],
  ["settings", "Configurações"]
];

function storefrontAdminSlugify(value) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 80);
}

function getStorefrontScopedOwnerId() {
  return storefrontAdminSlugify(syncConfig.supabaseUserId || getUsuarioAtual()?.id || usuarioAtualEmail || "local") || "local";
}

function getStorefrontAdminScopedKey(key = "") {
  const text = String(key);
  const scopedPrefixes = [
    "simplifica-storefront-admin-",
    "simplifica-storefront-leads-preview-",
    "simplifica-storefront-events-preview-",
    "simplifica-storefront-order-drafts-preview-"
  ];
  if (!scopedPrefixes.some((prefix) => text.startsWith(prefix))) return key;
  return `${key}:${getStorefrontScopedOwnerId()}`;
}

function storefrontAdminStorageGet(key) {
  try {
    return localStorage.getItem(getStorefrontAdminScopedKey(key)) ?? localStorage.getItem(key);
  } catch (_) {
    return null;
  }
}

function storefrontAdminStorageSet(key, value) {
  try {
    localStorage.setItem(getStorefrontAdminScopedKey(key), value);
  } catch (_) {}
}

function storefrontAdminStorageRemove(key) {
  try {
    localStorage.removeItem(getStorefrontAdminScopedKey(key));
    localStorage.removeItem(key);
  } catch (_) {}
}

function storefrontAdminRead(key, fallback) {
  try {
    const raw = storefrontAdminStorageGet(key);
    return raw ? JSON.parse(raw) : fallback;
  } catch (_) {
    return fallback;
  }
}

function storefrontAdminHasStoredValue(key) {
  try {
    return storefrontAdminStorageGet(key) !== null;
  } catch (_) {
    return false;
  }
}

function storefrontAdminWrite(key, value) {
  try {
    storefrontAdminStorageSet(key, JSON.stringify(value));
  } catch (_) {}
}

function getStorefrontEditorMode() {
  const mode = storefrontAdminStorageGet(STOREFRONT_ADMIN_KEYS.editorMode) || "simple";
  return mode === "complete" ? "complete" : "simple";
}

function setStorefrontEditorMode(mode = "simple") {
  const value = mode === "complete" ? "complete" : "simple";
  storefrontAdminStorageSet(STOREFRONT_ADMIN_KEYS.editorMode, value);
  mostrarToast(value === "complete" ? "Modo completo ativado." : "Modo simples ativado.", "info", 1800);
  renderApp();
}

function getStorefrontActivityLocal() {
  const saved = storefrontAdminRead(STOREFRONT_ADMIN_KEYS.activity, []);
  return Array.isArray(saved) ? saved : [];
}

function registrarStorefrontActivity(title, description = "") {
  const item = {
    id: `activity-${Date.now()}-${Math.random().toString(16).slice(2)}`,
    title,
    description,
    created_at: new Date().toISOString()
  };
  storefrontAdminWrite(STOREFRONT_ADMIN_KEYS.activity, [item, ...getStorefrontActivityLocal()].slice(0, 30));
}

function marcarStorefrontAlteracoesPendentes(detail = "Edição em andamento") {
  try {
    storefrontAdminStorageSet(STOREFRONT_ADMIN_KEYS.dirty, JSON.stringify({
      dirty: true,
      detail,
      updatedAt: new Date().toISOString()
    }));
  } catch (_) {}
  const target = document.querySelector("[data-storefront-save-state]");
  if (target) target.innerHTML = renderStorefrontSaveState(getStorefrontAdminViewModel(), { inline: true });
}

function limparStorefrontAlteracoesPendentes(detail = "Alterações salvas") {
  try {
    storefrontAdminStorageSet(STOREFRONT_ADMIN_KEYS.dirty, JSON.stringify({
      dirty: false,
      detail,
      updatedAt: new Date().toISOString()
    }));
    storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.autosave);
  } catch (_) {}
}

function getStorefrontDirtyState() {
  try {
    const saved = JSON.parse(storefrontAdminStorageGet(STOREFRONT_ADMIN_KEYS.dirty) || "null");
    return saved && typeof saved === "object" ? saved : { dirty: false };
  } catch (_) {
    return { dirty: false };
  }
}

let storefrontAutosaveTimer = null;

function serializeStorefrontForm(form) {
  const data = {};
  if (!form?.elements) return data;
  Array.from(form.elements).forEach((field) => {
    if (!field?.name || field.type === "file" || field.disabled) return;
    if (field.type === "checkbox") data[field.name] = !!field.checked;
    else if (field.type === "radio") {
      if (field.checked) data[field.name] = field.value;
    } else {
      data[field.name] = field.value;
    }
  });
  return data;
}

function getStorefrontSessionRecoveryState() {
  return {
    tab: storefrontAdminStorageGet(STOREFRONT_ADMIN_KEYS.tab) || "overview",
    editorMode: getStorefrontEditorMode(),
    path: window.location.pathname,
    search: window.location.search,
    scrollY: Math.max(0, Math.round(window.scrollY || 0)),
    savedAt: new Date().toISOString(),
    appVersion: APP_VERSION
  };
}

function storefrontScheduleAutosave(scope = "general", payload = {}) {
  clearTimeout(storefrontAutosaveTimer);
  storefrontAutosaveTimer = setTimeout(() => {
    const draft = {
      scope,
      payload: payload && typeof payload === "object" ? payload : {},
      recovery: getStorefrontSessionRecoveryState()
    };
    storefrontAdminWrite(STOREFRONT_ADMIN_KEYS.autosave, draft);
    storefrontAdminWrite(STOREFRONT_ADMIN_KEYS.recovery, draft.recovery);
    if (!navigator.onLine) storefrontQueuePendingAction(`autosave:${scope}`, draft.payload);
    marcarStorefrontAlteracoesPendentes("Rascunho salvo automaticamente neste aparelho");
    const indicator = document.querySelector("[data-storefront-autosave-indicator]");
    if (indicator) indicator.textContent = `Salvo automaticamente às ${new Date().toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" })}`;
  }, 700);
}

function storefrontFlushAutosaveNow() {
  const form = document.querySelector("#storefrontAppearanceForm, .storefront-form-card form, form.app-form");
  if (!form) return;
  if (!getStorefrontDirtyState().dirty) return;
  const route = parseStorefrontPublicRoute(location.pathname);
  const adminRoute = parseStorefrontAdminRoute(location.pathname);
  if (!route && !adminRoute && telaAtual !== "lojaAdmin" && telaAtual !== "lojaOnline") return;
  const draft = {
    scope: storefrontAdminStorageGet(STOREFRONT_ADMIN_KEYS.tab) || "general",
    payload: serializeStorefrontForm(form),
    recovery: getStorefrontSessionRecoveryState()
  };
  storefrontAdminWrite(STOREFRONT_ADMIN_KEYS.autosave, draft);
  storefrontAdminWrite(STOREFRONT_ADMIN_KEYS.recovery, draft.recovery);
}

function getStorefrontAutosaveDraft() {
  const draft = storefrontAdminRead(STOREFRONT_ADMIN_KEYS.autosave, null);
  if (!draft || typeof draft !== "object" || !draft.recovery?.savedAt) return null;
  return draft;
}

function aplicarStorefrontAutosavePayload(draft) {
  if (!draft?.payload || typeof draft.payload !== "object") return false;
  const payload = draft.payload;
  const store = getStorefrontAdminStoreLocal();
  if (draft.scope === "appearance" || draft.scope === "banner") {
    const next = {
      ...store,
      name: payload.storeName?.trim?.() || store.name,
      slug: storefrontAdminSlugify(payload.storeSlug || store.slug || payload.storeName || store.name),
      description: payload.storeDescription ?? store.description,
      whatsapp: String(payload.storeWhatsApp || store.whatsapp || "").replace(/\D/g, ""),
      instagram: payload.storeInstagram ?? store.instagram,
      logo_url: payload.storeLogoUrl || store.logo_url,
      banner_url: payload.storeBannerUrl || store.banner_url,
      theme_config: {
        ...(store.theme_config || {}),
        primary: normalizarCorTemaControlado(payload.storePrimary || store.theme_config?.primary || "#00BFA6", normalizarTemaLojaOnline(payload.storeThemeMode || store.theme_config?.mode || getStoreThemeSaved()), "primary"),
        accent: normalizarCorTemaControlado(payload.storeAccent || store.theme_config?.accent || "#FF8A1F", normalizarTemaLojaOnline(payload.storeThemeMode || store.theme_config?.mode || getStoreThemeSaved()), "secondary"),
        mode: normalizarTemaLojaOnline(payload.storeThemeMode || store.theme_config?.mode || getStoreThemeSaved())
      }
    };
    storefrontAdminSaveStore(next);
    return true;
  }
  if (draft.scope === "product") {
    storefrontAdminWrite(STOREFRONT_ADMIN_KEYS.editingProductSeed, {
      id: payload.productId || "",
      title: payload.productTitle || "",
      slug: payload.productSlug || "",
      erp_product_id: payload.erpProductId || "",
      category_id: payload.productCategory || "",
      price: payload.productPrice || "",
      compare_price: payload.productComparePrice || "",
      price_mode: payload.productPriceMode || "fixed",
      estimated_production_time: payload.productTime || "",
      stock_mode: payload.productStockMode || "unlimited",
      stock_quantity: payload.productStockQuantity || "",
      show_price: payload.productShowPrice !== false,
      visible: payload.productVisible !== false,
      featured: !!payload.productFeatured,
      is_customizable: payload.productCustomizable !== false,
      description: payload.productDescription || "",
      public_observations: payload.productObservations || ""
    });
    storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.editingProduct);
    return true;
  }
  if (draft.scope === "category") {
    storefrontAdminStorageSet(STOREFRONT_ADMIN_KEYS.editingCategory, payload.categoryId || "");
    return true;
  }
  return false;
}

function restaurarStorefrontAutosaveLocal() {
  const draft = getStorefrontAutosaveDraft();
  if (!draft) {
    mostrarToast("Nenhum rascunho local encontrado.", "info", 2200);
    return;
  }
  const restored = aplicarStorefrontAutosavePayload(draft);
  if (draft.recovery?.tab) storefrontAdminStorageSet(STOREFRONT_ADMIN_KEYS.tab, draft.recovery.tab);
  if (draft.recovery?.editorMode) storefrontAdminStorageSet(STOREFRONT_ADMIN_KEYS.editorMode, draft.recovery.editorMode);
  marcarStorefrontAlteracoesPendentes("Rascunho local recuperado");
  mostrarToast(restored ? "Rascunho local recuperado." : "Sessão de edição recuperada.", "sucesso", 2600);
  renderApp();
  setTimeout(() => window.scrollTo({ top: Number(draft.recovery?.scrollY || 0), behavior: "smooth" }), 80);
}

function descartarStorefrontAutosaveLocal() {
  storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.autosave);
  storefrontAdminStorageRemove(STOREFRONT_ADMIN_KEYS.recovery);
  limparStorefrontAlteracoesPendentes("Rascunho local descartado");
  mostrarToast("Rascunho local descartado.", "info", 2200);
  renderApp();
}

function renderStorefrontRecoveryNotice() {
  const draft = getStorefrontAutosaveDraft();
  if (!draft) return "";
  const when = new Date(draft.recovery.savedAt).toLocaleString("pt-BR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" });
  return `
    <div class="storefront-recovery-card">
      <strong>Rascunho local encontrado</strong>
      <small>${escaparHtml(when)} • ${escaparHtml(draft.scope || "edição")}</small>
      <div>
        <button type="button" onclick="restaurarStorefrontAutosaveLocal()">Retomar</button>
        <button type="button" onclick="descartarStorefrontAutosaveLocal()">Descartar</button>
      </div>
    </div>
  `;
}

function storefrontQueuePendingAction(type = "draft", payload = {}) {
  const queue = storefrontAdminRead(STOREFRONT_ADMIN_KEYS.offlineQueue, []);
  const next = Array.isArray(queue) ? queue : [];
  next.unshift({
    id: `store-queue-${Date.now()}-${Math.random().toString(16).slice(2)}`,
    type,
    payload,
    status: navigator.onLine ? "pending" : "offline",
    createdAt: new Date().toISOString(),
    appVersion: APP_VERSION
  });
  storefrontAdminWrite(STOREFRONT_ADMIN_KEYS.offlineQueue, next.slice(0, 30));
}

function storefrontFlushPendingQueue() {
  const queue = storefrontAdminRead(STOREFRONT_ADMIN_KEYS.offlineQueue, []);
  if (!Array.isArray(queue) || !queue.length) return;
  const pending = queue.filter((item) => item.status !== "completed");
  storefrontAdminWrite(STOREFRONT_ADMIN_KEYS.offlineQueue, pending.map((item) => ({
    ...item,
    status: navigator.onLine ? "waiting-sync" : "offline",
    lastAttemptAt: new Date().toISOString()
  })).slice(0, 30));
}

function storefrontIsDefaultText(value = "", defaults = []) {
  const text = normalizarTextoBusca(value);
  if (!text) return true;
  return defaults.some((item) => text === normalizarTextoBusca(item));
}

function storefrontIsDemoImage(value = "") {
  const text = String(value || "").toLowerCase();
  return !text || text.includes("storefront-demo") || text.startsWith("data:image/svg+xml");
}

function storefrontIsDemoProduct(product = {}) {
  const id = String(product.id || "");
  const title = String(product.title || product.name || "");
  return !!(
    product.__demo
    || product.__template
    || id.startsWith("demo-")
    || id.startsWith("template-")
    || storefrontIsDefaultText(title, ["Produto exemplo", "Produto da loja", "Peça sob encomenda"])
  );
}

function getStorefrontPublicationChecklist(vm = getStorefrontAdminViewModel()) {
  const store = vm.store || {};
  const contact = getStorefrontContactConfig(store);
  const theme = store.theme_config || {};
  const visibleProducts = (vm.products || []).filter((product) => product.visible !== false);
  const realProducts = visibleProducts.filter((product) => !storefrontIsDemoProduct(product));
  const validCategories = (vm.categories || []).filter((cat) => cat.visible !== false && !cat.__demo && !cat.__template && String(cat.name || "").trim());
  const demoProducts = visibleProducts.filter(storefrontIsDemoProduct);
  const invalidPriceProducts = realProducts.filter((product) => {
    const mode = String(product.price_mode || "fixed");
    if (mode === "quote" || product.show_price === false) return false;
    return Number(product.price || 0) <= 0;
  });
  const genericStoreName = storefrontIsDefaultText(store.name, ["Minha loja 3D", "Minha loja criativa", "Minha empresa 3D", "Loja Online", "NE3D", "Simplifica 3D"]);
  const genericDescription = storefrontIsDefaultText(store.description, [
    "Produtos personalizados, brindes e peças sob encomenda em impressão 3D.",
    "Produtos personalizados, utilidades e peças sob encomenda com acabamento profissional.",
    "Sua vitrine de impressão 3D integrada ao ERP."
  ]);
  const required = [
    {
      id: "store-name",
      title: "Nome da loja",
      description: genericStoreName ? "Troque o nome padrão pelo nome público da sua marca." : "Informe o nome público da loja.",
      area: "appearance",
      done: !!String(store.name || "").trim() && !genericStoreName
    },
    {
      id: "store-logo",
      title: "Logo personalizada",
      description: "Adicione uma logo própria para a loja representar sua marca.",
      area: "appearance",
      done: !storefrontIsDemoImage(store.logo_url)
    },
    {
      id: "store-banner",
      title: "Banner principal personalizado",
      description: "Substitua o banner padrão por uma imagem da marca, produto ou vitrine.",
      area: "banner",
      done: !storefrontIsDemoImage(store.banner_url)
    },
    {
      id: "store-whatsapp",
      title: "WhatsApp de contato",
      description: "Configure o WhatsApp para clientes solicitarem orçamento.",
      area: "contacts",
      done: String(contact.whatsapp || "").replace(/\D/g, "").length >= 10
    },
    {
      id: "store-social",
      title: "E-mail ou rede social",
      description: "Adicione e-mail, Instagram ou Facebook para dar confiança ao cliente.",
      area: "contacts",
      done: !!(contact.email || contact.instagram || contact.facebook)
    },
    {
      id: "store-products",
      title: "Produto real publicado",
      description: demoProducts.length ? "Substitua os produtos de exemplo por pelo menos 1 produto real." : "Adicione pelo menos 1 produto real visível.",
      area: "products",
      done: realProducts.length >= 1
    },
    {
      id: "store-product-prices",
      title: "Preços dos produtos válidos",
      description: invalidPriceProducts.length ? `Corrija ${invalidPriceProducts.length} produto(s) com preço zerado ou inválido.` : "Produtos com preço exibido precisam ter valor maior que zero.",
      area: "products",
      done: invalidPriceProducts.length === 0
    },
    {
      id: "store-categories",
      title: "Categorias válidas",
      description: "Crie ou confirme categorias reais para organizar a vitrine.",
      area: "categories",
      done: validCategories.length >= 1
    },
    {
      id: "store-description",
      title: "Descrição da loja",
      description: "Escreva uma descrição curta que represente a marca e o tipo de produto.",
      area: "appearance",
      done: !!String(store.description || "").trim() && !genericDescription
    },
    {
      id: "store-primary-color",
      title: "Cor principal definida",
      description: "Escolha uma cor principal para padronizar botões e destaques.",
      area: "appearance",
      done: !!String(theme.primary || "").trim()
    }
  ];
  const warnings = [
    {
      id: "store-favicon",
      title: "Favicon/ícone da loja",
      description: "Recomendado para reforçar a marca quando a loja for compartilhada.",
      area: "appearance",
      done: !!(store.favicon_url || theme.favicon_url || store.logo_url)
    },
    {
      id: "store-hours",
      title: "Horário de atendimento",
      description: "Opcional, mas ajuda o cliente a entender quando será respondido.",
      area: "contacts",
      done: !!contact.hours
    },
    {
      id: "store-address",
      title: "Endereço ou atendimento online",
      description: "Opcional, útil para lojas com retirada local ou região definida.",
      area: "contacts",
      done: !!contact.address
    },
    {
      id: "store-images",
      title: "Imagens dos produtos",
      description: "Use fotos reais para melhorar a percepção profissional da vitrine.",
      area: "products",
      done: realProducts.every((product) => !storefrontIsDemoImage(getStorefrontProductImage(product, vm.images || [])))
    }
  ];
  const demoItems = [
    demoProducts.length ? `${demoProducts.length} produto(s) de exemplo` : "",
    storefrontIsDemoImage(store.banner_url) ? "banner padrão" : "",
    storefrontIsDemoImage(store.logo_url) ? "logo padrão" : "",
    (vm.categories || []).some((cat) => cat.__demo || cat.__template) ? "categorias de modelo" : "",
    genericDescription ? "texto genérico da loja" : ""
  ].filter(Boolean);
  return {
    required,
    warnings,
    demoItems,
    missing: required.filter((item) => !item.done),
    recommended: warnings.filter((item) => !item.done),
    ready: required.every((item) => item.done) && !demoItems.length
  };
}

function abrirCorrecaoChecklistLoja(area = "appearance") {
  fecharPopup();
  if (area === "contacts" || area === "publish" || area === "theme") {
    abrirStoreVisualPanel(area === "theme" ? "theme" : area);
    return;
  }
  abrirStorefrontAdminRoute(area || "appearance");
}

function renderStorefrontPublicationChecklistModal(checklist = getStorefrontPublicationChecklist(), { intent = "publicar" } = {}) {
  const primaryArea = checklist.missing[0]?.area || checklist.recommended[0]?.area || "appearance";
  const completed = checklist.required.filter((item) => item.done).length;
  const progress = Math.round((completed / Math.max(1, checklist.required.length)) * 100);
  const vm = getStorefrontPublicViewModel();
  const previewImage = vm.store?.banner_url || vm.store?.logo_url || "/assets/simplifica-brand-cover.jpg";
  const actionLabel = {
    appearance: "Ir para aparência",
    banner: "Ir para banner",
    products: "Ir para produtos",
    categories: "Ir para categorias",
    contacts: "Ir para contato",
    settings: "Ir para configurações"
  }[primaryArea] || "Corrigir agora";
  return `
    <div class="modal-backdrop store-publication-check-backdrop" role="dialog" aria-modal="true">
      <section class="modal-card store-publication-check-modal">
        <div class="modal-header">
          <div>
            <span class="status-badge badge-warning">Checklist obrigatório</span>
            <h2>Finalize sua loja antes de ${escaparHtml(intent)}</h2>
            <p class="muted">A loja precisa representar sua marca antes de ser compartilhada com clientes.</p>
          </div>
          <button class="icon-button" type="button" onclick="fecharPopup()" title="Fechar">✕</button>
        </div>
        <div class="store-publication-progress">
          <div><strong>Loja pronta: ${progress}%</strong><span>${completed}/${checklist.required.length} itens essenciais</span></div>
          <i aria-hidden="true"><b style="width:${progress}%"></b></i>
        </div>
        <div class="store-publication-preview">
          <div>
            <span>Visualização final</span>
            <strong>${escaparHtml(getStorefrontDisplayName(vm.store))}</strong>
            <small>${escaparHtml(vm.store?.description || "Confira a identidade, produtos e contatos antes de compartilhar.")}</small>
          </div>
          <img src="${escaparAttr(previewImage)}" alt="${escaparAttr(getStorefrontDisplayName(vm.store))}" loading="lazy" decoding="async">
        </div>
        ${checklist.demoItems.length ? `
          <div class="store-publication-demo-alert">
            <strong>Você ainda está utilizando conteúdo de demonstração:</strong>
            <ul>${checklist.demoItems.map((item) => `<li>${escaparHtml(item)}</li>`).join("")}</ul>
          </div>
        ` : ""}
        <div class="store-publication-check-list">
          ${checklist.required.map((item) => `
            <button type="button" class="${item.done ? "done" : "pending"}" onclick="abrirCorrecaoChecklistLoja('${escaparAttr(item.area)}')">
              <i>${item.done ? "✓" : "!"}</i>
              <span><strong>${escaparHtml(item.title)}</strong><small>${escaparHtml(item.done ? "Tudo certo." : item.description)}</small></span>
            </button>
          `).join("")}
        </div>
        ${checklist.recommended.length ? `
          <details class="store-publication-recommended">
            <summary>Itens recomendados para uma publicação mais profissional</summary>
            ${checklist.recommended.map((item) => `<button type="button" onclick="abrirCorrecaoChecklistLoja('${escaparAttr(item.area)}')">${escaparHtml(item.title)}</button>`).join("")}
          </details>
        ` : ""}
        <div class="actions">
          <button class="btn secondary" type="button" onclick="fecharPopup()">Depois</button>
          <button class="btn" type="button" onclick="abrirCorrecaoChecklistLoja('${escaparAttr(primaryArea)}')">${escaparHtml(actionLabel)}</button>
        </div>
      </section>
    </div>
  `;
}

function renderStorefrontPublishedModal(store = getStorefrontAdminStoreLocal()) {
  const shareUrl = getStorefrontPublicUrl({ slug: store.slug, view: "home" });
  return `
    <div class="modal-backdrop store-publication-check-backdrop" role="dialog" aria-modal="true">
      <section class="modal-card store-publication-check-modal store-publication-success-modal">
        <div class="store-publication-success-mark">✓</div>
        <h2>Loja publicada com sucesso</h2>
        <p>Seu link já pode ser compartilhado. A vitrine continua usando a mesma estrutura segura do ERP e você pode voltar para editar quando quiser.</p>
        <div class="store-publication-share-box">
          <span>Link da vitrine</span>
          <strong>${escaparHtml(shareUrl)}</strong>
        </div>
        <div class="actions">
          <button class="btn secondary" type="button" onclick="fecharPopup(); window.location.href='${escaparAttr(getStorefrontPublicRoutePath({ slug: store.slug, view: "home" }))}'">Ver como cliente</button>
          <button class="btn" type="button" onclick="compartilharLojaPublica('${escaparAttr(shareUrl)}')">Compartilhar loja</button>
        </div>
      </section>
    </div>
  `;
}

function exigirChecklistPublicacaoLoja({ intent = "publicar", silent = false } = {}) {
  const policy = getPlanPolicy();
  if (!policy.publicStore) {
    if (!silent) {
      const mensagem = intent === "compartilhar"
        ? "O link público e o compartilhamento da loja ficam disponíveis no plano Start ou Pro."
        : "Sua loja pode ser editada no plano Grátis, mas a publicação pública fica disponível no Start ou Pro.";
      if (typeof mostrarModalLimitePlano === "function") {
        mostrarModalLimitePlano(`${mensagem}<br><br><strong>Sua loja está pronta para ser publicada.</strong><br>Ative um plano pago para liberar o link público, remover a marca Simplifica 3D e compartilhar sua vitrine.`);
      } else {
        mostrarToast(mensagem, "aviso", 5200);
      }
    }
    return false;
  }
  const checklist = getStorefrontPublicationChecklist();
  if (checklist.ready) return true;
  if (!silent) {
    const popup = document.getElementById("popup");
    if (popup) popup.innerHTML = renderStorefrontPublicationChecklistModal(checklist, { intent });
    else mostrarToast("Finalize o checklist da loja antes de publicar ou compartilhar.", "aviso", 4200);
  }
  return false;
}

function getStorefrontOwnerIdLocal() {
  return String(syncConfig.supabaseUserId || getUsuarioAtual()?.supabaseUserId || getUsuarioAtual()?.id || getUsuarioAtual()?.email || usuarioAtualEmail || "local").trim();
}

function isStorefrontStagingEnvironment() {
  const url = String(syncConfig.supabaseUrl || "").toLowerCase();
  const host = String(location.hostname || "").toLowerCase();
  return url.includes("dcaqiatgftkjxyewlhgi") || host.includes("staging") || host.includes("homolog");
}

function isStorefrontDemoPreviewAllowed() {
  return isAmbienteLocal() || isStorefrontStagingEnvironment();
}

