async function enviarLeadLojaPublica(event) {
  event?.preventDefault?.();
  const form = event?.target;
  const productId = form?.productId?.value || "";
  const { vm, product } = getStorefrontPublicVmProduto(productId);
  if (!product || !vm.store) return mostrarToast("Produto indisponível.", "erro", 3200);
  const lead = {
    customer_name: form?.customerName?.value?.trim() || null,
    customer_phone: String(form?.customerPhone?.value || "").replace(/\D/g, "") || null,
    customer_note: form?.customerNote?.value?.trim() || null
  };
  const whatsapp_message = montarMensagemProdutoLojaPublica(product, vm, lead);
  await registrarLeadLojaPublica(vm, product, { ...lead, whatsapp_message });
  registrarEventoLojaPublica("lead_created", { product_id: product.id }, { silent: true });
  fecharPopup();
  abrirWhatsappLojaPublica(whatsapp_message);
}

async function enviarCarrinhoLojaPublica(event) {
  event?.preventDefault?.();
  const form = event?.target;
  const vm = getStorefrontPublicViewModel();
  const summary = getStorefrontPublicCartSummary(vm);
  if (!summary.items.length) return mostrarToast("Adicione um produto antes de enviar.", "info", 2800);
  const lead = {
    customer_name: form?.customerName?.value?.trim() || null,
    customer_phone: String(form?.customerPhone?.value || "").replace(/\D/g, "") || null,
    customer_note: form?.customerNote?.value?.trim() || null
  };
  const whatsapp_message = montarMensagemCarrinhoLojaPublica(vm, summary, lead);
  await registrarLeadCarrinhoLojaPublica(vm, summary, { ...lead, whatsapp_message });
  registrarEventoLojaPublica("lead_created", { source: "cart" }, { silent: true });
  fecharPopup();
  abrirWhatsappLojaPublica(whatsapp_message);
}

async function registrarLeadLojaPublica(vm, product, lead = {}) {
  const item = { title: product.title, quantity: 1, price: Number(product.price || 0), product_id: product.id };
  const payload = {
    store_id: vm.store.id,
    owner_id: vm.store.owner_id,
    customer_name: lead.customer_name,
    customer_phone: lead.customer_phone,
    customer_note: lead.customer_note,
    items_json: [item],
    subtotal: Number(product.price || 0),
    whatsapp_message: lead.whatsapp_message,
    status: "novo",
    source: "storefront-public"
  };
  try {
    if (vm.source === "supabase" && !String(vm.store.id || "").startsWith("store-")) {
      await storefrontPublicRequest("/rest/v1/store_cart_leads", {
        method: "POST",
        headers: { Prefer: "return=minimal" },
        body: JSON.stringify(payload)
      });
      return;
    }
  } catch (error) {
    registrarStorefrontDebugLeve("lead_falhou", "Lead de produto não foi salvo no Supabase; fallback local será usado.", { message: error?.message || String(error) });
    console.warn("[Storefront public] lead best-effort failed", error);
  }
  try {
    const current = JSON.parse(localStorage.getItem(STOREFRONT_PUBLIC_LEADS_KEY) || "[]");
    current.unshift({ ...payload, id: `public-lead-${Date.now()}`, created_at: new Date().toISOString() });
    localStorage.setItem(STOREFRONT_PUBLIC_LEADS_KEY, JSON.stringify(current.slice(0, 120)));
    const adminLeads = getStorefrontPreviewLeadsLocal();
    storefrontAdminWrite("simplifica-storefront-leads-preview-v1", [{ ...payload, id: `public-lead-${Date.now()}`, created_at: new Date().toISOString() }, ...adminLeads].slice(0, 120));
  } catch (error) {
    registrarStorefrontDebugLeve("persistencia_falhou", "Fallback local do lead de produto falhou.", { message: error?.message || String(error) });
  }
}

async function registrarLeadCarrinhoLojaPublica(vm, summary, lead = {}) {
  const payload = {
    store_id: vm.store.id,
    owner_id: vm.store.owner_id,
    customer_name: lead.customer_name,
    customer_phone: lead.customer_phone,
    customer_note: lead.customer_note,
    items_json: summary.items.map((item) => ({ title: item.product.title, quantity: item.quantity, price: item.price, product_id: item.product.id })),
    subtotal: Number(summary.subtotal || 0),
    whatsapp_message: lead.whatsapp_message,
    status: "novo",
    source: "storefront-cart"
  };
  try {
    if (vm.source === "supabase" && !String(vm.store.id || "").startsWith("store-")) {
      await storefrontPublicRequest("/rest/v1/store_cart_leads", {
        method: "POST",
        headers: { Prefer: "return=minimal" },
        body: JSON.stringify(payload)
      });
      setStorefrontPublicCart([]);
      return;
    }
  } catch (error) {
    registrarStorefrontDebugLeve("lead_falhou", "Lead do carrinho não foi salvo no Supabase; fallback local será usado.", { message: error?.message || String(error) });
    console.warn("[Storefront public] cart lead best-effort failed", error);
  }
  try {
    const localLead = { ...payload, id: `public-cart-lead-${Date.now()}`, created_at: new Date().toISOString() };
    const current = JSON.parse(localStorage.getItem(STOREFRONT_PUBLIC_LEADS_KEY) || "[]");
    localStorage.setItem(STOREFRONT_PUBLIC_LEADS_KEY, JSON.stringify([localLead, ...current].slice(0, 120)));
    const adminLeads = getStorefrontPreviewLeadsLocal();
    storefrontAdminWrite("simplifica-storefront-leads-preview-v1", [localLead, ...adminLeads].slice(0, 120));
    setStorefrontPublicCart([]);
  } catch (error) {
    registrarStorefrontDebugLeve("persistencia_falhou", "Fallback local do lead do carrinho falhou.", { message: error?.message || String(error) });
  }
}

async function registrarEventoLojaPublica(eventType, metadata = {}, options = {}) {
  const vm = getStorefrontPublicViewModel();
  if (!vm.store?.id) return;
  const payload = { store_id: vm.store.id, product_id: metadata.product_id || null, event_type: eventType, metadata_json: metadata };
  try {
    if (vm.source === "supabase" && !String(vm.store.id || "").startsWith("store-")) {
      await storefrontPublicRequest("/rest/v1/store_events", {
        method: "POST",
        headers: { Prefer: "return=minimal" },
        body: JSON.stringify(payload)
      });
      return;
    }
  } catch (error) {
    registrarStorefrontDebugLeve("persistencia_falhou", "Evento da loja pública não foi registrado no Supabase; fallback local será usado.", {
      eventType,
      message: error?.message || String(error)
    });
    if (!options.silent) console.warn("[Storefront public] event failed", error);
  }
  try {
    const current = JSON.parse(localStorage.getItem(STOREFRONT_PUBLIC_EVENTS_KEY) || "[]");
    current.unshift({ ...payload, id: `public-event-${Date.now()}`, created_at: new Date().toISOString() });
    localStorage.setItem(STOREFRONT_PUBLIC_EVENTS_KEY, JSON.stringify(current.slice(0, 300)));
  } catch (_) {}
}

function marcarLojaPublicaNavegando() {
  document.body.classList.add("storefront-public-navigating");
  clearTimeout(storefrontPublicNavigationTimer);
  storefrontPublicNavigationTimer = setTimeout(() => {
    document.body.classList.remove("storefront-public-navigating");
  }, 220);
}

function salvarScrollLojaPublica() {
  if (telaAtual !== "lojaPublica") return;
  const path = getStorefrontPublicRoutePath();
  storefrontPublicScrollPositions.set(path, window.scrollY || document.documentElement.scrollTop || 0);
}

function restaurarScrollLojaPublica(path = getStorefrontPublicRoutePath(), fallback = 0) {
  const y = storefrontPublicScrollPositions.has(path) ? storefrontPublicScrollPositions.get(path) : fallback;
  requestAnimationFrame(() => window.scrollTo({ top: Math.max(0, Number(y) || 0), behavior: "auto" }));
}

function navegarLojaPublica(url, options = {}) {
  const destino = new URL(url, location.origin);
  const route = parseStorefrontPublicRoute(destino.pathname);
  if (!route) return false;
  if (options.forceClient) destino.searchParams.delete("admin");
  else if (getStorefrontPublicMode().admin && !destino.searchParams.has("admin")) destino.searchParams.set("admin", "1");
  salvarScrollLojaPublica();
  const previousPath = storefrontPublicLastPath || getStorefrontPublicRoutePath(getStorefrontPublicRoute());
  const nextPath = getStorefrontPublicRoutePath(route);
  if (!options.replace && previousPath && previousPath !== nextPath) {
    storefrontPublicInternalHistory.push(previousPath);
    if (storefrontPublicInternalHistory.length > 24) storefrontPublicInternalHistory.shift();
  }
  storefrontPublicRouteState = route;
  storefrontPublicLastPath = nextPath;
  telaAtual = "lojaPublica";
  marcarLojaPublicaNavegando();
  const nextUrl = `${destino.pathname}${destino.search || ""}${destino.hash || ""}`;
  if (!options.replace && nextUrl !== `${location.pathname}${location.search || ""}${location.hash || ""}`) {
    history.pushState({ simplifica: true, tela: "lojaPublica", loja: route }, document.title, nextUrl);
  } else if (options.replace) {
    history.replaceState({ simplifica: true, tela: "lojaPublica", loja: route }, document.title, nextUrl);
  }
  renderApp();
  const shouldRestore = options.restoreScroll === true;
  if (shouldRestore) restaurarScrollLojaPublica(getStorefrontPublicRoutePath(route), 0);
  else if (route.view === "product" || options.scrollTop) window.scrollTo({ top: 0, behavior: "smooth" });
  else if (destino.hash) document.querySelector(destino.hash)?.scrollIntoView?.({ behavior: "smooth", block: "start" });
  return true;
}

function configurarNavegacaoLojaPublica() {
  if (window.__simplificaStorefrontPublicNavigationConfigured) return;
  window.__simplificaStorefrontPublicNavigationConfigured = true;
  document.addEventListener("click", (event) => {
    const link = event.target.closest?.("a[href]");
    if (!link || event.defaultPrevented) return;
    if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    const href = link.getAttribute("href") || "";
    if (!href || href.startsWith("#") || link.target || link.hasAttribute("download")) return;
    const destino = new URL(href, location.origin);
    if (destino.origin !== location.origin || !parseStorefrontPublicRoute(destino.pathname)) return;
    const cliqueDentroDaLojaPublica = telaAtual === "lojaPublica" || !!link.closest(".store-public-shell");
    if (!cliqueDentroDaLojaPublica) return;
    event.preventDefault();
    navegarLojaPublica(destino.href);
  });
}

function navegarLojaPublicaLink(event, element, options = {}) {
  event?.preventDefault?.();
  event?.stopPropagation?.();
  const href = element?.href || element?.getAttribute?.("href") || "";
  if (!href) return false;
  navegarLojaPublica(href, options);
  return false;
}

function abrirWhatsappLojaPublica(mensagem = "") {
  const vm = getStorefrontPublicViewModel();
  const phone = normalizarWhatsappLojaPublica(vm.store?.whatsapp || appConfig.whatsappNumber || "");
  if (!phone) return mostrarToast("WhatsApp da loja ainda não foi configurado.", "erro", 3600);
  const configuredMessage = getStorefrontContactConfig(vm.store || {}).whatsapp_message;
  const texto = mensagem || `${configuredMessage || `Olá! Vim pela loja ${vm.store?.name || "Simplifica 3D"}.`}\n${getStorefrontPublicUrl(vm.route)}`;
  registrarEventoLojaPublica("whatsapp_click", { source: "storefront-public" }, { silent: true });
  window.open(`https://wa.me/${phone}?text=${encodeURIComponent(texto)}`, "_blank", "noopener");
}

function abrirWhatsappProdutoLojaPublica(productId = "") {
  const { vm, product } = getStorefrontPublicVmProduto(productId);
  if (!product) return mostrarToast("Produto não encontrado.", "erro", 3200);
  registrarEventoLojaPublica("whatsapp_click", { product_id: product.id }, { silent: true });
  abrirWhatsappLojaPublica(montarMensagemProdutoLojaPublica(product, vm));
}

function getStorefrontShareContext(url = getStorefrontPublicUrl()) {
  const vm = getStorefrontPublicViewModel();
  const route = parseStorefrontPublicRoute(new URL(url, location.origin).pathname) || vm.route || {};
  const product = route.view === "product"
    ? vm.products.find((item) => String(item.slug || item.id) === String(route.productSlug))
    : null;
  const category = route.view === "category"
    ? vm.categories.find((item) => String(item.slug || item.id) === String(route.categorySlug))
    : null;
  const title = product?.title
    ? `${product.title} | ${vm.store?.name || "Loja"}`
    : category?.name
      ? `${category.name} | ${vm.store?.name || "Loja"}`
      : vm.store?.name || "Loja Online";
  const text = product?.title
    ? `Olha este produto da loja ${vm.store?.name || "Simplifica 3D"}: ${product.title}`
    : category?.name
      ? `Veja a categoria ${category.name} da loja ${vm.store?.name || "Simplifica 3D"}.`
      : `Conheça a loja ${vm.store?.name || "Simplifica 3D"} no Simplifica 3D.`;
  const image = product ? getStorefrontProductImage(product, vm.images || []) : (vm.store?.banner_url || vm.store?.logo_url || "/assets/simplifica-brand-cover.jpg");
  const whatsappText = `${text}\n${url}`;
  return { vm, route, product, category, title, text, image, whatsappText, url };
}

function abrirPreviewCompartilhamentoLoja(url = getStorefrontPublicUrl()) {
  const context = getStorefrontShareContext(url);
  const popup = document.getElementById("popup");
  if (!popup) return prompt("Copie o link:", url);
  popup.innerHTML = `
    <div class="modal-backdrop store-share-preview-backdrop" role="dialog" aria-modal="true">
      <section class="modal-card store-share-preview-modal">
        <div class="modal-header">
          <div>
            <span class="status-badge">Compartilhamento</span>
            <h2>Link pronto para enviar</h2>
            <p class="muted">Use o compartilhamento nativo do celular, copie o link ou envie direto pelo WhatsApp.</p>
          </div>
          <button class="icon-button" type="button" onclick="fecharPopup()" title="Fechar">✕</button>
        </div>
        <article class="store-share-preview-card">
          ${context.image ? `<img src="${escaparAttr(context.image)}" loading="lazy" decoding="async" alt="${escaparAttr(context.title)}">` : ""}
          <div>
            <strong>${escaparHtml(context.title)}</strong>
            <span>${escaparHtml(context.text)}</span>
            <small>${escaparHtml(context.url)}</small>
          </div>
        </article>
        <div class="store-share-preview-actions">
          <button class="btn" type="button" onclick="compartilharLojaPublica('${escaparAttr(url)}', { forceNative: true })">Compartilhar no celular</button>
          <button class="btn secondary" type="button" onclick="abrirWhatsappCompartilhamentoLoja('${escaparAttr(url)}')">Enviar WhatsApp</button>
          <button class="btn ghost" type="button" onclick="copiarLinkLojaPublica('${escaparAttr(url)}')">Copiar link</button>
        </div>
      </section>
    </div>
  `;
}

function copiarLinkLojaPublica(url = getStorefrontPublicUrl()) {
  if (navigator.clipboard?.writeText) {
    navigator.clipboard.writeText(url).then(() => mostrarToast("Link copiado.", "sucesso", 2200)).catch(() => prompt("Copie o link:", url));
    return;
  }
  prompt("Copie o link:", url);
}

function abrirWhatsappCompartilhamentoLoja(url = getStorefrontPublicUrl()) {
  const { whatsappText } = getStorefrontShareContext(url);
  window.open(`https://wa.me/?text=${encodeURIComponent(whatsappText)}`, "_blank", "noopener");
}

function compartilharLojaPublica(url = getStorefrontPublicUrl(), options = {}) {
  const { vm, title, text } = getStorefrontShareContext(url);
  const mode = getStorefrontPublicMode(vm);
  if ((mode.admin || telaAtual === "lojaOnline" || telaAtual === "lojaAdmin") && vm?.limits?.shareEnabled === false) {
    mostrarToast("Compartilhamento da loja fica disponível no Start ou Pro.", "info", 4200);
    return;
  }
  if ((mode.admin || telaAtual === "lojaOnline" || telaAtual === "lojaAdmin") && !exigirChecklistPublicacaoLoja({ intent: "compartilhar" })) return;
  if (navigator.share) {
    navigator.share({ title, text, url }).then(() => registrarEventoLojaPublica("share_click", { url }, { silent: true })).catch(() => {});
    return;
  }
  if (!options.forceNative) {
    abrirPreviewCompartilhamentoLoja(url);
    return;
  }
  copiarLinkLojaPublica(url);
}

function getStorefrontCategoryName(vm, categoryId) {
  return vm.categories.find((cat) => String(cat.id) === String(categoryId))?.name || "Sem categoria";
}

function getStorefrontStockLabel(product = {}) {
  const mode = String(product.stock_mode || "unlimited");
  if (mode === "manual") return product.stock_quantity === null || product.stock_quantity === undefined ? "Estoque manual" : `${Number(product.stock_quantity || 0)} un.`;
  if (mode === "erp_linked") return "Vinculado ao estoque";
  if (mode === "unavailable") return "Indisponível";
  return "Sob encomenda";
}

