async function atualizarSeveridadeClusterDiagnostico(id, severity) {
  if (!isSuperAdmin() || !id || !severity) return;
  try {
    await requisicaoSupabase(`/rest/v1/app_bug_clusters?id=eq.${encodeURIComponent(id)}`, {
      method: "PATCH",
      headers: { Prefer: "return=minimal" },
      body: JSON.stringify({ severity })
    });
    appBugClustersRemotos = appBugClustersRemotos.map((item) => String(item.id) === String(id) ? { ...item, severity } : item);
    mostrarToast("Severidade do cluster atualizada.", "sucesso", 3500);
    renderApp();
  } catch (erro) {
    ErrorService.notify(erro, { area: "Superadmin", action: "Atualizar severidade cluster", errorKey: "UPDATE_BUG_CLUSTER_SEVERITY_FAILED" });
  }
}

async function atualizarNotaAdminCluster(id) {
  if (!isSuperAdmin() || !id) return;
  const atual = appBugClustersRemotos.find((item) => String(item.id) === String(id))?.admin_notes || "";
  const admin_notes = prompt("Nota administrativa do cluster", atual);
  if (admin_notes === null) return;
  try {
    await requisicaoSupabase(`/rest/v1/app_bug_clusters?id=eq.${encodeURIComponent(id)}`, {
      method: "PATCH",
      headers: { Prefer: "return=minimal" },
      body: JSON.stringify({ admin_notes })
    });
    appBugClustersRemotos = appBugClustersRemotos.map((item) => String(item.id) === String(id) ? { ...item, admin_notes } : item);
    mostrarToast("Nota administrativa salva.", "sucesso", 3500);
    renderApp();
  } catch (erro) {
    ErrorService.notify(erro, { area: "Superadmin", action: "Atualizar nota cluster", errorKey: "UPDATE_BUG_CLUSTER_NOTE_FAILED" });
  }
}

function filtrarRelatoriosAutomaticos(lista) {
  const filtros = getFiltrosTelemetriaSuperadmin();
  return lista.filter((item) => {
    if (filtros.severity && item.severity !== filtros.severity) return false;
    if (filtros.status && item.status !== filtros.status) return false;
    if (filtros.version && !String(item.app_version || "").toLowerCase().includes(filtros.version.toLowerCase())) return false;
    if (filtros.device && !String(item.device_model || "").toLowerCase().includes(filtros.device.toLowerCase())) return false;
    return true;
  });
}

function filtrarFeedbackReports(lista) {
  const filtros = getFiltrosTelemetriaSuperadmin();
  return lista.filter((item) => {
    if (filtros.feedbackStatus && item.status !== filtros.feedbackStatus) return false;
    if (filtros.feedbackType && item.type !== filtros.feedbackType) return false;
    return true;
  });
}

function filtrarSugestoesApp(lista) {
  const filtros = getFiltrosTelemetriaSuperadmin();
  return lista.filter((item) => {
    if (filtros.suggestionStatus && item.status !== filtros.suggestionStatus) return false;
    if (filtros.suggestionCategory && item.category !== filtros.suggestionCategory) return false;
    return true;
  });
}

function filtrarEventosDiagnostico(lista) {
  const filtros = getFiltrosTelemetriaSuperadmin();
  return lista.filter((item) => {
    if (filtros.eventType && item.event_type !== filtros.eventType) return false;
    if (filtros.severity && item.severity !== filtros.severity) return false;
    return true;
  });
}

function filtrarBugClusters(lista) {
  const filtros = getFiltrosTelemetriaSuperadmin();
  return lista.filter((item) => {
    if (filtros.clusterStatus && item.status !== filtros.clusterStatus) return false;
    if (filtros.severity && item.severity !== filtros.severity) return false;
    return true;
  });
}

function contarSugestoesPorCategoria(lista = []) {
  return lista.reduce((acc, item) => {
    const categoria = String(item.category || "geral").toLowerCase();
    acc[categoria] = (Number(acc[categoria]) || 0) + 1;
    return acc;
  }, {});
}

async function gerarRelatorioCodexDiagnostico(id = "", tipo = "bug") {
  if (!isSuperAdmin()) return;
  const bug = tipo === "cluster"
    ? appBugClustersRemotos.find((item) => String(item.id) === String(id)) || appBugClustersRemotos[0]
    : appErrorLogsRemotos.find((item) => String(item.id) === String(id)) || appErrorLogsRemotos[0] || appBugClustersRemotos[0];
  if (!bug) {
    mostrarToast("Nenhum diagnóstico disponível para gerar relatório.", "info");
    return;
  }
  const report = window.DiagnosticsService?.generateCodexTechnicalReport
    ? window.DiagnosticsService.generateCodexTechnicalReport({
      bug,
      events: appDiagnosticEventsRemotos.filter((event) => event.fingerprint && event.fingerprint === bug.fingerprint).slice(0, 8),
      feedbacks: appFeedbackReportsRemotos.slice(0, 5)
    })
    : `# Relatório técnico para correção\n\n## Resumo\n${bug.error_message || bug.summary || bug.fingerprint || "Diagnóstico coletado."}`;
  window.__codexDiagnosticsReport = report;
  try {
    navigator.clipboard?.writeText(report).catch(() => {});
  } catch (_) {}
  const exportPayload = {
    created_by: pareceUuid(syncConfig.supabaseUserId) ? syncConfig.supabaseUserId : null,
    report_title: `Relatório Codex - ${bug.title || bug.error_key || bug.fingerprint || "diagnóstico"}`.slice(0, 180),
    filters_json: {
      type: tipo,
      generated_from_id: id || bug.id || null,
      severity: bug.severity || null,
      status: bug.status || null
    },
    summary: String(bug.summary || bug.error_message || bug.error_key || bug.fingerprint || "Diagnóstico").slice(0, 900),
    technical_report: report,
    related_error_ids: tipo === "bug" && bug.id ? [bug.id] : [],
    related_feedback_ids: appFeedbackReportsRemotos.slice(0, 5).map((item) => item.id).filter(Boolean),
    related_cluster_ids: tipo === "cluster" && bug.id ? [bug.id] : [],
    status: "generated"
  };
  try {
    if (!syncConfig.supabaseAccessToken || !syncConfig.supabaseUrl) throw new Error("Supabase indisponível para salvar relatório técnico.");
    const salvo = await requisicaoSupabase("/rest/v1/app_bug_reports_exports?select=*", {
      method: "POST",
      headers: { Prefer: "return=representation" },
      body: JSON.stringify(exportPayload)
    });
    const item = Array.isArray(salvo) ? salvo[0] : salvo;
    if (item?.id) appBugReportsExportsRemotos = [item, ...appBugReportsExportsRemotos.filter((registro) => String(registro.id) !== String(item.id))].slice(0, 80);
    mostrarToast("Relatório técnico para Codex gerado e salvo.", "sucesso", 4200);
  } catch (erro) {
    appBugReportsExportsRemotos = [{ ...exportPayload, id: `local-${Date.now()}`, created_at: new Date().toISOString() }, ...appBugReportsExportsRemotos].slice(0, 80);
    mostrarToast("Relatório gerado localmente. Não foi possível salvar no Supabase agora.", "aviso", 5200);
    registrarErroAplicacaoSilencioso("SAVE_CODEX_REPORT_EXPORT_FAILED", erro, "Salvar relatório Codex");
  }
  renderApp();
}

function renderCodexDiagnosticsReport() {
  const report = window.__codexDiagnosticsReport || "";
  return `
    <div class="danger-zone">
      <div class="section-title-row">
        <h2 class="section-title">Relatórios para Codex</h2>
        <button class="btn secondary" type="button" onclick="gerarRelatorioCodexDiagnostico()">Gerar relatório técnico para Codex</button>
      </div>
      ${report ? `<textarea class="diagnostics-codex-report" rows="16" readonly>${escaparHtml(report)}</textarea>` : `<p class="empty">Selecione um bug ou cluster para gerar um relatório técnico estruturado.</p>`}
      <div class="history-list">
        ${appBugReportsExportsRemotos.map((item) => `
          <div class="history-item">
            <strong>${escaparHtml(item.report_title || "Relatório")}</strong>
            <span class="muted">${escaparHtml(item.status || "draft")} • ${item.created_at ? new Date(item.created_at).toLocaleString("pt-BR") : "-"}</span>
            <span>${escaparHtml(item.summary || "")}</span>
          </div>
        `).join("") || `<p class="empty">Nenhum relatório exportado ainda.</p>`}
      </div>
    </div>
  `;
}

